#!/usr/bin/env python3
# This file was generated by Cursor AI on 2026-04-15.

"""Generate LaTeX tabular tables from rewrite JSON files."""

from __future__ import annotations

import argparse
import json
import re
from pathlib import Path
from typing import Any


def format_formula(value: str) -> str:
    """Apply requested formula-to-LaTeX substitutions."""
    # Longer token first so "<->" is not partially replaced by "->".
    formatted = value.replace("<->", r"\leftrightarrow")
    formatted = formatted.replace("->", r"\rightarrow")
    formatted = formatted.replace("<=", r"\leq")
    formatted = formatted.replace(">=", r"\geq")

    # Symbolic variables.
    formatted = formatted.replace("a0", r"\phi")
    formatted = formatted.replace("a1", r"\psi")
    formatted = formatted.replace("a2", r"\xi")
    formatted = re.sub(r"\bb(\d+)\b", r"i_\1", formatted)
    formatted = re.sub(r"!\s*", r"\\neg ", formatted)

    # Temporal operators with arbitrary bounds, e.g. G[0, 3].
    formatted = re.sub(r"G\[(.*?)\]", r"\\Box_{[\1]}\\ ", formatted)
    formatted = re.sub(r"F\[(.*?)\]", r"\\lozenge_{[\1]}\\ ", formatted)
    formatted = re.sub(r"U\[(.*?)\]", r"\\ \\mathcal{U}_{[\1]}\\ ", formatted)
    formatted = re.sub(r"R\[(.*?)\]", r"\\ \\mathcal{R}_{[\1]}\\ ", formatted)

    # Binary logical operators.
    formatted = formatted.replace("&", r"\land")
    formatted = formatted.replace("|", r"\lor")
    return formatted


def extract_rows(path: Path) -> list[dict[str, Any]]:
    """Extract one table row per rewrite rule."""
    with path.open("r", encoding="utf-8") as handle:
        data = json.load(handle)

    rows: list[dict[str, Any]] = []
    for group_name in sorted(data.keys()):
        rewrites = data[group_name]
        for rewrite in rewrites:
            pre = format_formula(rewrite["pre"])
            post = format_formula(rewrite["post"])
            constraints = rewrite.get("constraints", [])
            if constraints:
                constraint_text = "; ".join(format_formula(c) for c in constraints)
            else:
                constraint_text = r"\text{none}"

            rows.append(
                {
                    "group": group_name,
                    "rewrite": rf"${pre} \mapsto {post}$",
                    "constraints": rf"${constraint_text}$",
                    "birewrite": r"\checkmark" if rewrite.get("birewrite", False) else r"\ding{55}",
                }
            )
    return rows


def render_table(rows: list[dict[str, Any]], title: str, caption: str) -> str:
    """Render one LaTeX tabular environment for a rewrite set."""
    lines = [
        r"\begin{table*}[t]",
        r"\centering",
        rf"\caption{{{caption}}}",
        title,
        r"\begin{tabular}{p{0.54\textwidth} p{0.25\textwidth} c}",
        r"\hline",
        r"Rewrite & Constraints & Bi-directional \\",
        r"\hline",
    ]

    for row in rows:
        lines.append(
            f"{row['rewrite']} & "
            f"{row['constraints']} & "
            f"{row['birewrite']} \\\\"
        )

    lines.extend([r"\hline", r"\end{tabular}", r"\end{table*}"])
    return "\n".join(lines)


def parse_args() -> argparse.Namespace:
    cur_dir = Path(__file__).parent
    rewrites_path = cur_dir / "rewrites.json"
    parser = argparse.ArgumentParser(
        description="Generate a LaTeX table summarizing rewrite groups."
    )
    parser.add_argument(
        "--rewrites",
        type=Path,
        default=rewrites_path,
        help="Path to the rewrites JSON file.",
    )
    parser.add_argument(
        "--output",
        type=Path,
        default=None,
        help="Optional output path. If omitted, prints to stdout.",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()

    rewrites_rows = extract_rows(args.rewrites)

    output_sections = [
        render_table(rewrites_rows, "Rewrites", "Rewrites"),
        "",
    ]
    output_text = "\n".join(output_sections)

    if args.output is None:
        print(output_text)
    else:
        args.output.write_text(output_text + "\n", encoding="utf-8")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
